def _avro_read_long(buf, pos):
    # Avro long: variable-length zig-zag encoded int (little-endian base128, zigzag)
    # Read varint (unsigned), then zigzag decode to signed.
    shift = 0
    result = 0
    while True:
        if pos >= len(buf):
            raise Exception("EOF reading long")
        b = buf[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        shift += 7
        if not (b & 0x80):
            break
    # Zigzag decode: (n >> 1) ^ -(n & 1)
    n = result
    return ((n >> 1) ^ -(n & 1), pos)

